package com.ryanjei.orushio.pve.paper;
import com.ryanjei.orushio.pve.application.GameApplicationService;import com.ryanjei.orushio.pve.economy.FarmEconomyLifecycleStep;import com.ryanjei.orushio.pve.map.BlockPoint;import org.bukkit.event.*;import org.bukkit.event.block.BlockBreakEvent;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.event.block.Action;import org.bukkit.inventory.EquipmentSlot;import java.time.Instant;
public final class FarmEconomyListener implements Listener{
 private final GameApplicationService games;private final FarmEconomyLifecycleStep economy;public FarmEconomyListener(GameApplicationService games,FarmEconomyLifecycleStep economy){this.games=games;this.economy=economy;}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void breakBlock(BlockBreakEvent event){var block=event.getBlock();economy.collect(games.current(),event.getPlayer().getUniqueId(),block.getWorld().getName(),new BlockPoint(block.getX(),block.getY(),block.getZ(),0,0),block.getType().name(),Instant.now());}
 @EventHandler(ignoreCancelled=true)public void interact(PlayerInteractEvent event){if(event.getHand()!=EquipmentSlot.HAND||event.getAction()!=Action.RIGHT_CLICK_BLOCK||event.getClickedBlock()==null)return;var block=event.getClickedBlock();var result=economy.purchase(games.current(),event.getPlayer().getUniqueId(),block.getWorld().getName(),new BlockPoint(block.getX(),block.getY(),block.getZ(),0,0));if(result==FarmEconomyLifecycleStep.PurchaseResult.IGNORED||result==FarmEconomyLifecycleStep.PurchaseResult.WRONG_SESSION)return;event.setCancelled(true);event.getPlayer().sendMessage(switch(result){case COMPLETED->"購入しました。";case INSUFFICIENT_POINTS->"Pointが不足しています。";case INVENTORY_FULL->"Inventoryに空きがありません。";case TIER_UNAVAILABLE->"現在のTierでは購入できません。";default->"このShopは利用できません。";});}
}
